"""Writes docs/LESSONS_REVIEW.md from assets/lessons/lessons.json: every lesson's text with what to check it against.
Run after editing lessons:  python3 tool/lessons_review.py
The owner checks each claim against the named IRS documents during the annual review (docs/ANNUAL_RULES_REVIEW.md),
then sets "verified": true on that lesson. Only verified lessons appear in release builds."""
import json

d = json.load(open('assets/lessons/lessons.json'))
tracks = {t['id']: t['title'] for t in d['tracks']}
out = ['# Learn lessons: review checklist', '',
       'Generated by `tool/lessons_review.py` from `assets/lessons/lessons.json`. Do not edit by hand.', '',
       'For each lesson: read every sentence against the documents listed under **Check against** (current tax year).',
       'Numbers appear as `{{placeholders}}`: they come from the verified rules file, so check that the right',
       'placeholder is used, not a value. When every claim checks out, set `"verified": true` on the lesson.',
       'Anything wrong or unsure: fix the text (or delete the sentence) first. Release builds show only verified lessons.', '']
done = sum(1 for l in d['lessons'] if l['verified'])
out += [f'**Status:** {done} of {len(d["lessons"])} verified.', '']
for l in d['lessons']:
    out += [f'## {"[x]" if l["verified"] else "[ ]"} {l["title"]}  (`{l["id"]}`, {tracks[l["track"]]})', '']
    for p in l['body']:
        out += [f'> {p}', '>']
    out += ['', '**Check against:**'] + [f'- {c}' for c in l['checkAgainst']]
    out += ['', f'Shown when: `{l["trigger"]}` · Your-numbers block: `{l["you"]}` · Button: `{l["action"]}` · '
            f'Source links (verified resources): {", ".join(l["sources"]) or "none"}', '']
open('docs/LESSONS_REVIEW.md', 'w').write('\n'.join(out))
print(f'{len(d["lessons"])} lessons, {done} verified -> docs/LESSONS_REVIEW.md')
